void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
class Original:public H8SEmulator {public:int rh()const{return lastread;}int wh()const{return lastwrite;}void histories(int a,int b){lastread=a;lastwrite=b;}int depth()const{return indent;}void depth(int n){indent=n;}};
uint32_t seed=0x2cf41c91;uint32_t rnd(){seed^=seed<<13;seed^=seed>>17;return seed^=seed<<5;}
struct Event {uint64_t time;uint32_t pc,sp,at,r0,r1,r6;uint8_t ccr,value;bool write;};
template<class C>struct Bus:H8SDevice {C&c;std::array<Event,128>events{};unsigned n=0,group=0;bool liveStatus=false;explicit Bus(C&x):c(x){}void record(uint32_t at,uint8_t v,bool w){check(n<events.size(),"bus overflow");events[n++]={c.cycles,uint32_t(c.getPC()),c.getSP(),at,uint32_t(c.reg32(0)),uint32_t(c.reg32(1)),uint32_t(c.reg32(6)),c.ccr,v,w};}uint8_t read(uint32_t at)override{auto v=at==0x600004&&!liveStatus?uint8_t(group==1?16:7):c.memory[at];record(at,v,false);return v;}void write(uint32_t at,uint8_t v)override{record(at,v,true);c.memory[at]=v;if(at==0x600000&&v==8)group=1;if(at==0x60000e)group=2;}};
struct F{std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<kstation::Stage1Cpu>b=std::make_unique<kstation::Stage1Cpu>();Bus<Original>x{*a};Bus<kstation::Stage1Cpu>y{*b};uint64_t graphs=0,phases=0,events=0,children=0,handlerCalls=0,activityCalls=0;uint32_t stack=0xffff00;
 explicit F(const std::vector<uint8_t>&r){a->loadmem(r.data(),unsigned(r.size()),0);b->loadmem(r.data(),unsigned(r.size()),0);for(auto q:std::array<std::pair<uint32_t,uint32_t>,8>{{{0xbfa0,0x1000},{0xc9b6,0x200},{0xcbb6,0x24a},{0xd000,0x1400},{0xfffd20,0x210},{0xffff00,0x80},{0xffffd0,4},{0x600000,16}}}){a->memmap(&x,q.first,q.second);b->memmap(&y,q.first,q.second);}}
 void byte(uint32_t p,uint8_t v){a->memory[p&0xffffff]=b->memory[p&0xffffff]=v;}void word(uint32_t p,uint16_t v){byte(p,v>>8);byte(p+1,v);}void wide(uint32_t p,uint32_t v){word(p,v>>16);word(p+2,v);}
 void prep(uint32_t pc,uint8_t flags){for(unsigned i=0;i<8;++i)a->regs[i].er=b->regs[i].er=int32_t(rnd());a->pc=a->makepc(pc);b->pc=b->makepc(pc);a->setSP(stack);b->setSP(stack);wide(stack,0x7000);a->ccr=b->ccr=flags;a->exr=b->exr=uint8_t(rnd());a->cycles=b->cycles=rnd();a->histories(0x20000,0x30000);b->histories(0x20000,0x30000);a->depth(2);b->irqDepth(2);a->pending_irqs=b->pending_irqs=0;a->pending_irqs_high=b->pending_irqs_high=0;a->interruptMode2=b->interruptMode2=false;x.n=y.n=0;x.group=y.group=0;}
 void equal(){bool ok=a->getPC()==b->getPC()&&a->cycles==b->cycles&&a->ccr==b->ccr&&a->exr==b->exr&&a->getSP()==b->getSP()&&a->rh()==b->readHistory()&&a->wh()==b->writeHistory()&&a->depth()==b->irqDepth();for(unsigned i=0;i<8;++i)ok&=a->regs[i].er==b->regs[i].er;if(!ok){std::fprintf(stderr,"PC=%x/%x cycles=%llu/%llu CCR=%x/%x SP=%x/%x R0=%x/%x R1=%x/%x R6=%x/%x history=%x/%x %x/%x\n",a->getPC(),b->getPC(),a->cycles,b->cycles,a->ccr,b->ccr,a->getSP(),b->getSP(),unsigned(a->reg32(0)),unsigned(b->reg32(0)),unsigned(a->reg32(1)),unsigned(b->reg32(1)),unsigned(a->reg32(6)),unsigned(b->reg32(6)),a->rh(),b->readHistory(),a->wh(),b->writeHistory());throw std::runtime_error("frame mismatch");}check(x.n==y.n,"bus count");for(unsigned i=0;i<x.n;++i){auto&p=x.events[i];auto&q=y.events[i];if(!(p.time==q.time&&p.pc==q.pc&&p.sp==q.sp&&p.at==q.at&&p.r0==q.r0&&p.r1==q.r1&&p.r6==q.r6&&p.ccr==q.ccr&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"bus at %x/%x, pc %x/%x ccr %x/%x time %llu/%llu\n",p.at,q.at,p.pc,q.pc,p.ccr,q.ccr,p.time,q.time);throw std::runtime_error("bus differs");}}events+=x.n;x.n=y.n=0;for(auto q:std::array<std::pair<uint32_t,uint32_t>,3>{{{0xc9b6,0x200},{0xfffd20,0x210},{0xfffef0,0x20}}})check(!std::memcmp(a->memory+q.first,b->memory+q.first,q.second),"RAM mismatch");}
 void oracle(){a->step();b->step();equal();}
 void runPart(){kstation::NativeVoicePartAddress t;unsigned n=0;while(!t.complete()){check(++n<12,"part hang");check(t.step(*b),"part phase");a->step();equal();++phases;}}
 void runRefresh(){kstation::NativeVoiceUpdate update;kstation::NativeVoiceAllocation voice;kstation::NativeDspTransfer dsp;x.liveStatus=y.liveStatus=true;unsigned n=0;do{check(++n<30000,"native refresh hang");auto pc=uint32_t(a->getPC());byte(0x600004,(pc==0x161a||pc==0x1628)?7:0x17);a->step();bool ok=update.step(*b);if(!ok)ok=voice.step(*b);if(!ok)ok=dsp.step(*b);check(ok,"native refresh child");equal();++phases;}while(update.active());x.liveStatus=y.liveStatus=false;}
 void runApply(kstation::MidiApplyControlTask::Kind kind,uint8_t part,uint8_t value,bool nativeRefresh=false){using T=kstation::MidiApplyControlTask;kstation::NativeMidiApplyControl t(kind,part,value);unsigned n=0;while(!t.task().complete()){check(++n<40,"CC apply hang");if(t.task().awaitingChild()){if(t.task().child()==T::Child::LookupPart)runPart();else if(nativeRefresh)runRefresh();else{auto at=uint32_t(a->getPC());auto u=a->memory[at],v=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,u);byte(at+1,v);}check(t.resumeChild(*b),"CC apply resume");++children;continue;}check(t.step(*b),"CC apply phase");a->step();equal();++phases;}}
 void apply(kstation::MidiApplyControlTask::Kind kind,uint8_t flags,uint8_t part,uint8_t value,uint8_t inhibit){using K=kstation::MidiApplyControlTask::Kind;prep(kind==K::Modulation?0x80f4:0x811a,flags);a->reg8(14)=b->reg8(14)=int8_t(part);a->reg8(13)=b->reg8(13)=int8_t(value);auto base=0xbfaa+16u*part;byte(base+14,inhibit);runApply(kind,part,value);check(uint32_t(a->getPC())==0x7000,"CC apply return");check(a->memory[base+(kind==K::Modulation?6:9)]==value,"CC apply value");++graphs;}
 void runGeneral(uint8_t control,uint8_t value){using T=kstation::MidiGeneralControlTask;kstation::NativeMidiGeneralControl t(control,value);unsigned n=0;while(!t.task().complete()){check(++n<100,"general control hang");if(t.task().awaitingChild()){auto child=t.task().child();if(child==T::Child::Match){kstation::NativeMidiEventHelper h(kstation::MidiEventHelperTask::Kind::ChannelMatch);while(!h.task().complete()){check(h.step(*b),"general match");a->step();equal();++phases;}}else if(child==T::Child::ClearHeld){kstation::NativeMidiClearNotes h;while(!h.task().complete()){check(h.step(*b),"general clear held");a->step();equal();++phases;}}else{auto at=uint32_t(a->getPC());auto u=a->memory[at],v=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,u);byte(at+1,v);}check(t.resumeChild(*b),"general control resume");++children;continue;}check(t.step(*b),"general control phase");a->step();equal();++phases;}}
 void connectedApply(kstation::MidiApplyControlTask::Kind kind,uint8_t flags,bool active){prep(kind==kstation::MidiApplyControlTask::Kind::Modulation?0x80f4:0x811a,flags);a->reg8(14)=b->reg8(14)=0;a->reg8(13)=b->reg8(13)=64;byte(0xd028,0);byte(0xd022,1);byte(0xbfb8,0);byte(0xbfb9,0);byte(0xc681,0);wide(0xd030,0xc600);byte(0xd034,0);word(0xd038,active?1:0);runApply(kind,0,64,true);check(uint32_t(a->getPC())==0x7000,"connected apply return");++graphs;}
 void general(uint8_t flags,uint8_t control,uint8_t value,bool match,uint8_t nrpn,uint8_t oldSustain,uint8_t patchFlags){prep(0x2ea8,flags);a->reg8(0)=b->reg8(0)=int8_t(control);a->reg8(8)=b->reg8(8)=int8_t(value);byte(0xcad5,2);byte(0xbb16,match?2:3);byte(0xcc00,nrpn);byte(0xcc01,oldSustain);byte(0xcc02,oldSustain);byte(0xbab4,patchFlags);runGeneral(control,value);check(uint32_t(a->getPC())==0x7000,"general return");++graphs;}
 void controlOwner(uint8_t flags,uint8_t controller,uint8_t value,bool match){using X=kstation::NativeMidiEvents::External;prep(0x2e34,flags);a->reg32(4)=b->reg32(4)=0xcab0;byte(0xcab0,controller);byte(0xcab1,value);byte(0xcad5,2);byte(0xbb16,match?2:3);byte(0xcc00,0x80);byte(0xcc01,0);byte(0xcc02,0);byte(0xbab4,0);byte(0xbfb8,0);kstation::NativeMidiEvents t;check(t.admitControl(*b,0x7000),"control owner admission");unsigned steps=0;while(uint32_t(a->getPC())!=0x7000||t.active()){check(++steps<100,"control owner hang");if(t.step(*b)){a->step();equal();++phases;continue;}equal();if(uint32_t(a->getPC())==0x7000&&!t.active())break;auto child=t.external();if(child==X::PartLookup){runPart();++children;continue;}uint32_t expected=child==X::PressureRefresh?0x785c:child==X::PressureCommit?0x5e64:child==X::CcModulation?0x80f4:child==X::CcBreath?0x811a:child==X::CcVolume?0x403c:child==X::AllSoundOff?0x7760:child==X::ReleaseAllVoices?0x7644:child==X::SetNrpn?0x575a:child==X::ReleaseSustain?0x76d6:child==X::ControlParameter?0x576a:0;check(expected&&uint32_t(a->getPC())==expected,"control external");auto u=a->memory[expected],v=a->memory[expected+1];byte(expected,0x54);byte(expected+1,0x70);oracle();byte(expected,u);byte(expected+1,v);++children;}++graphs;}
 void control(uint8_t flags,uint8_t controller,uint8_t value,bool match){using T=kstation::MidiControlTask;using C=T::Child;prep(0x2e34,flags);a->reg32(4)=b->reg32(4)=0xcab0;byte(0xcab0,controller);byte(0xcab1,value);byte(0xcad5,2);byte(0xbb16,match?2:3);byte(0xcc00,0x80);byte(0xcc01,0);byte(0xcc02,0);byte(0xbab4,0);byte(0xbfb8,0);kstation::NativeMidiControl t(0x7000);unsigned steps=0;while(!t.task().complete()){check(++steps<80,"control hang");if(t.task().awaitingChild()){auto child=t.task().child();if(child==C::StoreChannel||child==C::Match){kstation::NativeMidiEventHelper h(child==C::StoreChannel?kstation::MidiEventHelperTask::Kind::StoreChannel:kstation::MidiEventHelperTask::Kind::ChannelMatch,uint32_t(a->reg32(1)),uint8_t(a->reg8(8)));while(!h.task().complete()){check(h.step(*b),"control helper");a->step();equal();++phases;}}else if(child==C::Modulation||child==C::Breath)runApply(child==C::Modulation?kstation::MidiApplyControlTask::Kind::Modulation:kstation::MidiApplyControlTask::Kind::Breath,uint8_t(a->reg8(14)),uint8_t(a->reg8(13)));else if(child==C::General)runGeneral(uint8_t(a->reg8(0)),uint8_t(a->reg8(8)));else{auto at=uint32_t(a->getPC());auto u=a->memory[at],v=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,u);byte(at+1,v);}check(t.resumeChild(*b),"control resume");++children;continue;}check(t.step(*b),"control phase");a->step();equal();++phases;}check(uint32_t(a->getPC())==0x7000,"control return");++graphs;}
};
