int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"ROM size");F f(rom);for(auto kind:{kstation::MidiApplyControlTask::Kind::Modulation,kstation::MidiApplyControlTask::Kind::Breath})for(uint8_t flags:{uint8_t(0),uint8_t(0x80),uint8_t(0xff)})for(bool active:{false,true})f.connectedApply(kind,flags,active);for(auto kind:{kstation::MidiApplyControlTask::Kind::Modulation,kstation::MidiApplyControlTask::Kind::Breath})for(unsigned flags=0;flags<256;++flags)for(uint8_t part:{uint8_t(0),uint8_t(1),uint8_t(15),uint8_t(255)})for(uint8_t value:{uint8_t(0),uint8_t(1),uint8_t(63),uint8_t(127),uint8_t(255)})for(uint8_t inhibit:{uint8_t(0),uint8_t(1),uint8_t(255)})f.apply(kind,uint8_t(flags),part,value,inhibit);
 for(unsigned flags=0;flags<256;++flags)for(uint8_t c:{uint8_t(0),uint8_t(6),uint8_t(64),uint8_t(98),uint8_t(120),uint8_t(121),uint8_t(123),uint8_t(124),uint8_t(125),uint8_t(126),uint8_t(127),uint8_t(255)})for(uint8_t v:{uint8_t(0),uint8_t(1),uint8_t(63),uint8_t(64),uint8_t(127),uint8_t(255)})for(bool match:{false,true})for(uint8_t nrpn:{uint8_t(0),uint8_t(0x80)})for(uint8_t sustain:{uint8_t(0),uint8_t(16)})for(uint8_t patch:{uint8_t(0),uint8_t(4)})f.general(uint8_t(flags),c,v,match,nrpn,sustain,patch);
 for(unsigned flags=0;flags<256;++flags)for(uint8_t c:{uint8_t(1),uint8_t(2),uint8_t(7),uint8_t(32),uint8_t(64)})for(uint8_t v:{uint8_t(0),uint8_t(1),uint8_t(4),uint8_t(5),uint8_t(127)})for(bool match:{false,true})f.controlOwner(uint8_t(flags),c,v,match);
 for(unsigned control=0;control<256;++control)for(uint8_t flags:{uint8_t(0),uint8_t(0x80),uint8_t(0xff)})for(uint8_t value:{uint8_t(0),uint8_t(1),uint8_t(4),uint8_t(5),uint8_t(127),uint8_t(255)})for(bool match:{false,true})f.control(flags,uint8_t(control),value,match);
 for(unsigned flags=0;flags<256;++flags)for(uint8_t control:{uint8_t(1),uint8_t(2),uint8_t(7),uint8_t(32)})for(unsigned value=0;value<256;++value)for(bool match:{false,true})f.control(uint8_t(flags),control,uint8_t(value),match);
 std::printf("{\"passed\":true,\"graphs\":%llu,\"native_phases\":%llu,\"ordered_bus_events\":%llu,\"explicit_children\":%llu}\n",(unsigned long long)f.graphs,(unsigned long long)f.phases,(unsigned long long)f.events,(unsigned long long)f.children);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL: %s\n",e.what());return 1;}}
